[{"order":1,"type":"heading","text":"Networking in C# (Sockets and HTTP)"},{"order":2,"type":"paragraph","text":"This tutorial covers fundamental networking concepts in C# using sockets and HTTP. We'll explore how to create client-server applications using sockets for low-level communication and how to interact with web services using HTTP."},{"order":3,"type":"subheading","text":"Sockets"},{"order":4,"type":"paragraph","text":"Sockets provide a low-level interface for network communication. They allow you to establish connections between applications running on different machines or on the same machine. Sockets operate at the transport layer (TCP/UDP) of the OSI model."},{"order":5,"type":"subheading","text":"TCP Sockets (Connection-Oriented)"},{"order":6,"type":"paragraph","text":"TCP (Transmission Control Protocol) provides a reliable, connection-oriented communication channel. It guarantees that data is delivered in the correct order and without errors."},{"order":7,"type":"code","text":"// Server (TCP)
using System;
using System.Net;
using System.Net.Sockets;
using System.Text;

public class TCPServer
{
    public static void Main(string[] args)
    {
        TcpListener server = null;
        try
        {
            Int32 port = 13000;
            IPAddress localAddr = IPAddress.Parse("127.0.0.1");

            server = new TcpListener(localAddr, port);

            server.Start();

            Console.WriteLine("Server started on port {0}", port);

            while (true)
            {
                Console.WriteLine("Waiting for a connection...");

                TcpClient client = server.AcceptTcpClient();
                Console.WriteLine("Connected!");

                NetworkStream stream = client.GetStream();

                byte[] buffer = new byte[1024];
                int bytes = stream.Read(buffer, 0, buffer.Length);

                string data = Encoding.ASCII.GetString(buffer, 0, bytes);
                Console.WriteLine("Received: {0}", data);

                byte[] msg = Encoding.ASCII.GetBytes("Message Received");
                stream.Write(msg, 0, msg.Length);
                Console.WriteLine("Sent: {0}", "Message Received");

                client.Close();
            }
        }
        catch (SocketException e)
        {
            Console.WriteLine("SocketException: {0}", e);
        }
        finally
        {
            server.Stop();
        }

        Console.WriteLine("\nPress Enter to continue...");
        Console.Read();
    }
}"},{"order":8,"type":"code","text":"// Client (TCP)
using System;
using System.Net.Sockets;
using System.Text;

public class TCPClient
{
    public static void Main(string[] args)
    {
        try
        {
            Int32 port = 13000;
            TcpClient client = new TcpClient("127.0.0.1", port);

            NetworkStream stream = client.GetStream();

            string message = "Hello from client";
            byte[] data = Encoding.ASCII.GetBytes(message);

            stream.Write(data, 0, data.Length);
            Console.WriteLine("Sent: {0}", message);

            byte[] buffer = new byte[1024];
            int bytes = stream.Read(buffer, 0, buffer.Length);
            string responseData = Encoding.ASCII.GetString(buffer, 0, bytes);
            Console.WriteLine("Received: {0}", responseData);

            client.Close();
        }
        catch (ArgumentNullException e)
        {
            Console.WriteLine("ArgumentNullException: {0}", e);
        }
        catch (SocketException e)
        {
            Console.WriteLine("SocketException: {0}", e);
        }

        Console.WriteLine("\nPress Enter to continue...");
        Console.Read();
    }
}"},{"order":9,"type":"subheading","text":"UDP Sockets (Connectionless)"},{"order":10,"type":"paragraph","text":"UDP (User Datagram Protocol) provides a connectionless, unreliable communication channel. Data is sent in datagrams, and there is no guarantee of delivery or order. UDP is suitable for applications where speed is more important than reliability, such as streaming media or online games."},{"order":11,"type":"code","text":"// Server (UDP)
using System;
using System.Net;
using System.Net.Sockets;
using System.Text;

public class UDPServer
{
    public static void Main(string[] args)
    {
        UdpClient server = new UdpClient(11000);
        IPEndPoint remoteEP = new IPEndPoint(IPAddress.Any, 0);

        try
        {
            Console.WriteLine("Waiting for broadcast...");

            byte[] data = server.Receive(ref remoteEP);

            string message = Encoding.ASCII.GetString(data, 0, data.Length);
            Console.WriteLine("Received: {0} from {1}", message, remoteEP.Address.ToString());

            string response = "Message Received";
            byte[] sendbuf = Encoding.ASCII.GetBytes(response);
            server.Send(sendbuf, sendbuf.Length, remoteEP);

        }
        catch (Exception e)
        {
            Console.WriteLine(e.ToString());
        }
        finally
        {
            server.Close();
        }
    }
}"},{"order":12,"type":"code","text":"// Client (UDP)
using System;
using System.Net;
using System.Net.Sockets;
using System.Text;

public class UDPClient
{
    public static void Main(string[] args)
    {
        UdpClient client = new UdpClient();
        IPEndPoint ep = new IPEndPoint(IPAddress.Parse("127.0.0.1"), 11000);
        client.Connect(ep);

        string message = "Hello from client";
        byte[] sendbuf = Encoding.ASCII.GetBytes(message);
        client.Send(sendbuf, sendbuf.Length);

        byte[] recv = client.Receive(ref ep);
        string response = Encoding.ASCII.GetString(recv);

        Console.WriteLine("Received: {0}", response);

        client.Close();
    }
}"},{"order":13,"type":"subheading","text":"HTTP (Hypertext Transfer Protocol)"},{"order":14,"type":"paragraph","text":"HTTP is an application-layer protocol used for distributed, collaborative, hypermedia information systems. It is the foundation of data communication for the World Wide Web. In C#, you can use the `HttpClient` class to make HTTP requests."},{"order":15,"type":"code","text":"// HTTP GET Request
using System;
using System.Net.Http;
using System.Threading.Tasks;

public class HTTPGetExample
{
    public static async Task Main(string[] args)
    {
        using (HttpClient client = new HttpClient())
        {
            try
            {
                HttpResponseMessage response = await client.GetAsync("https://jsonplaceholder.typicode.com/todos/1");
                response.EnsureSuccessStatusCode(); // Throw exception if not a success code.
                string responseBody = await response.Content.ReadAsStringAsync();
                Console.WriteLine(responseBody);
            }
            catch (HttpRequestException e)
            {
                Console.WriteLine("\nException Caught!");
                Console.WriteLine("Message :{0} ", e.Message);
            }
        }
    }
}"},{"order":16,"type":"code","text":"// HTTP POST Request
using System;
using System.Net.Http;
using System.Text;
using System.Threading.Tasks;

public class HTTPPostExample
{
    public static async Task Main(string[] args)
    {
        using (HttpClient client = new HttpClient())
        {
            try
            {
                string jsonPayload = "{\"userId\": 1, \"title\": \"Sample Post\", \"completed\": false}";
                StringContent content = new StringContent(jsonPayload, Encoding.UTF8, "application/json");

                HttpResponseMessage response = await client.PostAsync("https://jsonplaceholder.typicode.com/todos", content);
                response.EnsureSuccessStatusCode();
                string responseBody = await response.Content.ReadAsStringAsync();
                Console.WriteLine(responseBody);
            }
            catch (HttpRequestException e)
            {
                Console.WriteLine("\nException Caught!");
                Console.WriteLine("Message :{0} ", e.Message);
            }
        }
    }
}"},{"order":17,"type":"subheading","text":"Conclusion"},{"order":18,"type":"paragraph","text":"This tutorial provided a basic overview of networking in C# using sockets and HTTP. You can use these concepts as a foundation for building more complex network applications."}]
